export function sound(canvas,status,project){const [c,w,h]=fit(canvas),color=COLORS[project.params.sound%4];c.fillStyle='#070f14';c.fillRect(0,0,w,h);const portrait=w<520?Math.min(140,w*.44):Math.min(330,w*.38),cx=portrait/2+15,cy=h/2+5,r=Math.min(portrait*.33,h*.32);c.strokeStyle='#29464f';c.beginPath();c.moveTo(portrait,18);c.lineTo(portrait,h-18);c.stroke();text(c,'ENGINE GEOMETRY',12,21,w<520?6:8);for(let j=0;j<4;j++){c.strokeStyle=color+(j===3?'59':'20');c.lineWidth=.7;c.beginPath();c.arc(cx,cy,r*(.45+j*.18),0,Math.PI*2);c.stroke();}for(let layer=0;layer<7;layer++){c.beginPath();for(let i=0;i<=240;i++){let a=i/240*Math.PI*2,mod=Math.sin(a*(project.params.sound===1?3:2)+project.params.shape*Math.PI)*project.params.tone,rad=r*(.35+layer*.05)+mod*r*(.08+project.params.shape*.16),x=cx+Math.cos(a)*rad,y=cy+Math.sin(a)*rad;if(i===0)c.moveTo(x,y);else c.lineTo(x,y);}c.strokeStyle=color+Math.round((.13+layer*.07)*255).toString(16).padStart(2,'0');c.stroke();}c.fillStyle=COLORS[1];let a=project.params.shape*Math.PI*2;c.beginPath();c.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,2.5,0,Math.PI*2);c.fill();text(c,`TONE ${Math.round(project.params.tone*100)}%`,12,h-17,7);let left=portrait+15,right=w-15,mid=h*.48,height=h*.48;for(let i=0;i<=8;i++){let x=left+(right-left)*i/8;c.strokeStyle='#28444d70';c.beginPath();c.moveTo(x,h*.2);c.lineTo(x,h*.78);c.stroke();}text(c,w<520?'LIVE OUTPUT':'LIVE OUTPUT / OSCILLOSCOPE',left,21,w<520?6:8);c.beginPath();for(let i=0;i<256;i++){let x=left+i*(right-left)/255,y=mid-(status[16+i]||0)*height*.43;if(i===0)c.moveTo(x,y);else c.lineTo(x,y);}c.strokeStyle=color;c.shadowColor=color;c.shadowBlur=3;c.lineWidth=1.2;c.stroke();c.shadowBlur=0;for(let bin=0;bin<32;bin++){let real=0,imag=0;for(let n=0;n<256;n+=2){let angle=Math.PI*2*(bin+1)*n/256;real+=(status[16+n]||0)*Math.cos(angle);imag-=(status[16+n]||0)*Math.sin(angle);}let extent=Math.min(h*.1,Math.hypot(real,imag)*.7);c.fillStyle=color+'70';c.fillRect(left+bin*(right-left)/32,h*.88-extent,(right-left)/32*.65,Math.max(.5,extent));}}
export function bus(canvas,track,status){const [c,w,h]=fit(canvas),color=COLORS[track];c.clearRect(0,0,w,h);c.beginPath();for(let i=0;i<160;i++){let x=i*w/159,y=h*.7-(status[272+track*320+i*2]||0)*h*.6;if(i===0)c.moveTo(x,y);else c.lineTo(x,y);}c.strokeStyle=color;c.lineWidth=1.1;c.stroke();c.lineTo(w,h*.84);c.lineTo(0,h*.84);c.closePath();c.fillStyle=color+'18';c.fill();}
